H.background();
const v = H.plot2d({ xMin: -1, xMax: 11, yMin: -1.4, yMax: 1.4 });
v.grid(); v.axes();
const p = Math.max(P.p, 0.01);
const h = 6.626e-34;
const lam = h / (p * 1e-25);
const lamNm = lam * 1e9;
const k = 2 * Math.PI / Math.max(lamNm, 0.001);
const scaleK = k * 0.5;
v.fn(x => Math.sin(scaleK * (x + 0.5) - 2.2 * t), { color: H.colors.accent, width: 3 });
const px = 5 + 4 * Math.sin(t * 0.7);
v.dot(px, Math.sin(scaleK * (px + 0.5) - 2.2 * t), { r: 6, fill: H.colors.accent2 });
H.text("de Broglie: lambda = h / p", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("Matter waves: faster particle -> shorter wavelength", 24, 52, { color: H.colors.sub, size: 13 });
H.text("p = " + p.toFixed(2) + " x10^-25 kg m/s", 24, 78, { color: H.colors.sub, size: 13 });
H.text("lambda = " + lamNm.toFixed(2) + " nm", 24, 98, { color: H.colors.accent2, size: 13 });
